#!/usr/bin/env python3
"""Archive generated bytes in a private bucket with content-addressed parts.

Never overwrite; download and verify every part before committing a SQL receipt.
Credentials stay in explicit local env files and never enter URLs or logs.
"""
import argparse
from concurrent.futures import ThreadPoolExecutor, as_completed
import hashlib
import io
from http.client import HTTPSConnection, HTTPException
import threading
import json
from pathlib import Path
import sys
import time
from urllib.error import HTTPError
from urllib.request import HTTPRedirectHandler
from urllib.parse import urlsplit

from supabase_corpus_bulk import load_database_url, PROJECT
from supabase_snapshot_documents import file_inventory

PART_BYTES = 4 * 1024 * 1024
BUCKET = "dvns-snapshots"


class NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise HTTPError(newurl, code, "Redirect refused", headers, fp)


def file_parts(path, expected_sha256, part_bytes=PART_BYTES):
    with path.open("rb") as handle:
        digest = hashlib.sha256()
        while block := handle.read(1024 * 1024):
            digest.update(block)
        if digest.hexdigest() != expected_sha256:
            raise ValueError("source hash mismatch before upload")
        handle.seek(0)
        while part := handle.read(part_bytes):
            yield part


def verified_stream(stream, expected_sha256, expected_bytes):
    digest = hashlib.sha256()
    count = 0
    while block := stream.read(1024 * 1024):
        digest.update(block)
        count += len(block)
        if count > expected_bytes:
            raise ValueError("download exceeds expected bytes")
    if count != expected_bytes or digest.hexdigest() != expected_sha256:
        raise ValueError("download hash or size mismatch")
    return digest.hexdigest()


def storage_credentials(path):
    values = dict(
        line.split("=", 1)
        for line in path.read_text(encoding="utf-8").splitlines()
        if "=" in line and not line.lstrip().startswith("#")
    )
    base = values.get("DVNS_SUPABASE_URL", "").strip().strip("\"'")
    key = values.get("DVNS_SUPABASE_SECRET_KEY", "").strip().strip("\"'")
    if base != f"https://{PROJECT}.supabase.co" or not key.startswith("sb_secret_"):
        raise ValueError("invalid Storage target or server key")
    return base, key


class StorageClient:
    def __init__(self, base, key):
        self.base = base + "/storage/v1"
        self.headers = {"apikey": key, "User-Agent": "dvns-private-archive"}
        self.host = urlsplit(base).hostname
        self.local = threading.local()
        self.known_parts = set()

    def open(self, path, method="GET", data=None, extra=None):
        headers = {**self.headers, **(extra or {})}
        for attempt in range(3):
            if getattr(self.local, "connection", None) is None:
                # One verified TLS connection per worker, reused for POST and GET.
                self.local.connection = HTTPSConnection(self.host, timeout=45)
            connection = self.local.connection
            try:
                connection.request(
                    method, "/storage/v1" + path, body=data, headers=headers
                )
                response = connection.getresponse()
                if 300 <= response.status < 400:
                    connection.close()
                    self.local.connection = None
                    NoRedirect().redirect_request(
                        None,
                        None,
                        response.status,
                        "Redirect refused",
                        response.headers,
                        "",
                    )
                if response.status >= 400:
                    body = response.read(8192)
                    status = response.status
                    reason = response.reason
                    response_headers = response.headers
                    connection.close()
                    self.local.connection = None
                    if (status == 429 or status >= 500) and attempt < 2:
                        time.sleep(10 * 2**attempt)
                        continue
                    raise HTTPError(
                        self.base + path,
                        status,
                        reason,
                        response_headers,
                        io.BytesIO(body),
                    )
                return response
            except HTTPError:
                raise
            except (OSError, HTTPException):
                connection.close()
                self.local.connection = None
                if attempt == 2:
                    raise ValueError(
                        "Storage network failure; credentials omitted"
                    ) from None
                time.sleep(0.5 * 2**attempt)

    def ensure_bucket(self):
        try:
            with self.open("/bucket/" + BUCKET) as response:
                bucket = json.load(response)
        except HTTPError as error:
            status = error.code
            try:
                detail = json.loads(error.read(2048))
            except (ValueError, UnicodeDecodeError):
                detail = {}
            error.close()
            missing = status == 404 or (
                status == 400
                and str(detail.get("statusCode")) == "404"
                and detail.get("error") == "Bucket not found"
            )
            if not missing:
                raise ValueError(
                    f"Storage bucket lookup failed HTTP {status}"
                ) from None
            payload = json.dumps(
                {
                    "id": BUCKET,
                    "name": BUCKET,
                    "public": False,
                    "file_size_limit": PART_BYTES,
                }
            ).encode()
            with self.open(
                "/bucket", "POST", payload, {"Content-Type": "application/json"}
            ) as response:
                response.read()
            with self.open("/bucket/" + BUCKET) as response:
                bucket = json.load(response)
        if bucket.get("public") is not False:
            raise ValueError("archive bucket must be private")

    def put_part(self, part):
        if len(part) > PART_BYTES:
            raise ValueError("archive object exceeds bounded part size")
        sha = hashlib.sha256(part).hexdigest()
        key = "sha256/" + sha
        try:
            if key not in self.known_parts:
                with self.open(
                    "/object/" + BUCKET + "/" + key,
                    "POST",
                    part,
                    {"Content-Type": "application/octet-stream", "x-upsert": "false"},
                ) as response:
                    response.read()
        except HTTPError as error:
            status = error.code
            body = error.read(2048).decode("utf-8", "replace")
            error.close()
            duplicate = status == 409 or (
                status == 400
                and ("already exists" in body.lower() or "Duplicate" in body)
            )
            if not duplicate:
                raise ValueError(f"Storage upload failed HTTP {status}") from None
        with self.open("/object/authenticated/" + BUCKET + "/" + key) as response:
            verified_stream(response, sha, len(part))
        self.known_parts.add(key)
        return {"key": key, "sha256": sha, "bytes": len(part)}

    def archive(self, path, item):
        parts = []
        whole = hashlib.sha256()
        total = 0
        for part in file_parts(path, item["source_sha256"]):
            parts.append(self.put_part(part))
            whole.update(part)
            total += len(part)
        if whole.hexdigest() != item["source_sha256"] or total != item["source_bytes"]:
            raise ValueError("source changed while archiving")
        return {
            "source_sha256": item["source_sha256"],
            "source_bytes": total,
            "bucket": BUCKET,
            "parts": parts,
        }


def commit_receipts(conn, receipts):
    from psycopg.types.json import Jsonb

    with conn.transaction():
        with conn.cursor() as cursor:
            cursor.executemany(
                """INSERT INTO dvns_snapshots.blobs(source_sha256,source_bytes,bucket,parts)
                                  VALUES (%s,%s,%s,%s) ON CONFLICT (source_sha256) DO NOTHING""",
                [
                    (
                        r["source_sha256"],
                        r["source_bytes"],
                        r["bucket"],
                        Jsonb(r["parts"]),
                    )
                    for r in receipts
                ],
            )
        rows = conn.execute(
            "SELECT source_sha256,source_bytes,bucket,parts FROM dvns_snapshots.blobs WHERE source_sha256=ANY(%s)",
            ([r["source_sha256"] for r in receipts],),
        ).fetchall()
        actual = {sha: (size, bucket, parts) for sha, size, bucket, parts in rows}
        for receipt in receipts:
            if actual.get(receipt["source_sha256"]) != (
                receipt["source_bytes"],
                receipt["bucket"],
                receipt["parts"],
            ):
                raise ValueError("stored blob receipt mismatch")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--root", type=Path, default=Path(__file__).resolve().parents[2]
    )
    parser.add_argument("--env-file", type=Path, required=True)
    parser.add_argument("--storage-env-file", type=Path, required=True)
    parser.add_argument("--workers", type=int, default=1, choices=range(1, 5))
    parser.add_argument("--path", action="append")
    args = parser.parse_args()
    import psycopg

    inventory = file_inventory(
        args.root,
        json.loads((args.root / "scripts/ci/generated-artifacts.json").read_bytes()),
    )
    if args.path:
        inventory = [item for item in inventory if item["path"] in args.path]
        if len(inventory) != len(set(args.path)):
            parser.error("unknown archive path")
    unique = {item["source_sha256"]: item for item in inventory}
    base, key = storage_credentials(args.storage_env_file)
    client = StorageClient(base, key)
    try:
        client.ensure_bucket()
        with psycopg.connect(
            load_database_url(args.env_file),
            autocommit=True,
            connect_timeout=15,
            prepare_threshold=None,
        ) as conn:
            client.known_parts = {
                part["key"]
                for (parts,) in conn.execute("SELECT parts FROM dvns_snapshots.blobs")
                for part in parts
            }
            pending = []
            done = 0
            total_bytes = 0
            with ThreadPoolExecutor(max_workers=args.workers) as executor:
                futures = {
                    executor.submit(
                        client.archive, args.root / item["path"], item
                    ): item["path"]
                    for item in unique.values()
                }
                try:
                    for future in as_completed(futures):
                        try:
                            result = future.result()
                        except HTTPError as error:
                            status = error.code
                            try:
                                detail = json.loads(error.read(2048))
                            except (ValueError, UnicodeDecodeError):
                                detail = {}
                            error.close()
                            message = str(
                                detail.get("message", detail.get("error", ""))
                            ).replace(key, "[REDACTED]")[:160]
                            raise ValueError(
                                f"Storage HTTP {status}: {message}; file {futures[future]}"
                            ) from None
                        pending.append(result)
                        done += 1
                        total_bytes += result["source_bytes"]
                        if len(pending) >= 64:
                            commit_receipts(conn, pending)
                            pending = []
                            print(
                                json.dumps(
                                    {
                                        "event": "archived",
                                        "blobs": done,
                                        "expected": len(unique),
                                        "bytes": total_bytes,
                                    }
                                ),
                                flush=True,
                            )
                    if pending:
                        commit_receipts(conn, pending)
                except BaseException:
                    for future in futures:
                        future.cancel()
                    raise
            print(
                json.dumps(
                    {
                        "event": "archive_complete",
                        "files": len(inventory),
                        "unique_blobs": done,
                        "bytes": total_bytes,
                        "bucket": BUCKET,
                    }
                ),
                flush=True,
            )
    except Exception as error:
        print(
            json.dumps(
                {
                    "event": "failed",
                    "error_type": type(error).__name__,
                    "reason": (
                        str(error)
                        if isinstance(error, ValueError)
                        else "Archive operation failed; credentials omitted"
                    ),
                }
            ),
            flush=True,
        )
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
